SELECT USER AS "User",
           SYS_CONTEXT('USERENV', 'CURRENT_SCHEMA') AS "Schema",
           SYSTIMESTAMP AS "Checked At";

CREATE TABLE thomas_app_data (
        order_id  NUMBER PRIMARY KEY,
        app_data  JSON NOT NULL
    );

    INSERT INTO thomas_app_data (order_id, app_data)
    SELECT order_id,
           JSON_OBJECT(
               'screen'    VALUE 'service-order-detail',
               'showTotal' VALUE 'true' FORMAT JSON,
               'features'  VALUE JSON_ARRAY('live-status', 'activation-preferences')
               RETURNING JSON
           )
    FROM (
        SELECT order_id
        FROM service_orders
        ORDER BY order_id
        FETCH FIRST 1 ROW ONLY
    );

    COMMIT;

SELECT data AS order_document
    FROM service_orders_dv
    FETCH FIRST 1 ROW ONLY;

INSERT INTO service_orders_dv (data)
    SELECT JSON(
      '{
        "_id": 900001,
        "subscriberId": 1,
        "siteId": 1,
        "periodStart": "2026-09-01",
        "periodEnd": "2026-10-01",
        "status": "pending",
        "total": 250.00,
        "activationFee": 0,
        "items": [
          {
            "orderLineId": 990001,
            "planId": 1,
            "connectionCount": 2,
            "monthlyFee": 125.00
          }
        ]
      }'
    )
    WHERE NOT EXISTS (
      SELECT 1
      FROM service_orders
      WHERE order_id = 900001
    );

    COMMIT;

UPDATE service_orders_dv
    SET data = JSON_TRANSFORM(data, SET '$.status' = 'confirmed')
    WHERE JSON_VALUE(data, '$._id' RETURNING NUMBER) = 900001;

    COMMIT;

DROP TABLE IF EXISTS otto_plan_demand_settings;

    CREATE TABLE otto_plan_demand_settings (
          setting_name  VARCHAR2(30),
          setting_value VARCHAR2(4000)
        );

    INSERT INTO otto_plan_demand_settings (setting_name, setting_value)
    VALUES ('ALGO_NAME', 'ALGO_GENERALIZED_LINEAR_MODEL');

    INSERT INTO otto_plan_demand_settings (setting_name, setting_value)
    VALUES ('PREP_AUTO', 'ON');

    INSERT INTO otto_plan_demand_settings (setting_name, setting_value)
    VALUES ('ODMS_RANDOM_SEED', '20260604');

    COMMIT;

    DECLARE
      l_model_count NUMBER;
    BEGIN
      SELECT COUNT(*)
      INTO l_model_count
      FROM user_mining_models
      WHERE model_name = 'OTTO_PLAN_DEMAND_SURGE_MODEL';

      IF l_model_count > 0 THEN
        DBMS_DATA_MINING.DROP_MODEL('OTTO_PLAN_DEMAND_SURGE_MODEL');
      END IF;
    END;
    /

    BEGIN
      DBMS_DATA_MINING.CREATE_MODEL(
        model_name           => 'OTTO_PLAN_DEMAND_SURGE_MODEL',
        mining_function      => DBMS_DATA_MINING.CLASSIFICATION,
        data_table_name      => 'OML_PLAN_DEMAND_TRAINING_V',
        case_id_column_name  => 'PLAN_ID',
        target_column_name   => 'SURGE_LABEL',
        settings_table_name  => 'OTTO_PLAN_DEMAND_SETTINGS'
      );
    END;
    /

BEGIN
      DBMS_CLOUD_AI.SET_ATTRIBUTE(
        profile_name    => 'genai',
        attribute_name  => 'object_list',
        attribute_value => '[{"owner": "' || USER || '", "name": "SERVICE_PLANS"}, {"owner": "' || USER || '", "name": "SERVICE_ORDERS"}, {"owner": "' || USER || '", "name": "SERVICE_ORDER_LINES"}, {"owner": "' || USER || '", "name": "SUBSCRIBERS"}]'
      );
    END;
    /

SELECT DBMS_CLOUD_AI.GENERATE(
             prompt       => 'Which five service plans have the highest contracted monthly charges? Sum service_order_lines.line_total only for service_orders whose order_status is exactly ''confirmed'', ''active'', or ''completed'' (stored lowercase).',
             profile_name => 'genai',
             action       => 'showsql'
           ) AS generated_sql;

SELECT DBMS_CLOUD_AI.GENERATE(
             prompt       => 'Which five service plans have the highest contracted monthly charges? Sum service_order_lines.line_total only for service_orders whose order_status is exactly ''confirmed'', ''active'', or ''completed'' (stored lowercase).',
             profile_name => 'genai',
             action       => 'runsql'
           ) AS answer;

SELECT DBMS_CLOUD_AI.GENERATE(
             prompt       => 'Show the five service plans with the highest contracted monthly charges. Include plan name, category, summed line_total, and summed connection_count. Include only service_orders whose order_status is exactly ''confirmed'', ''active'', or ''completed'' (stored lowercase); exclude activation fees.',
             profile_name => 'genai',
             action       => 'showsql'
           ) AS generated_sql;

SELECT DBMS_CLOUD_AI.GENERATE(
             prompt       => 'Show the five service plans with the highest contracted monthly charges. Include plan name, category, summed line_total, and summed connection_count. Include only service_orders whose order_status is exactly ''confirmed'', ''active'', or ''completed'' (stored lowercase); exclude activation fees.',
             profile_name => 'genai',
             action       => 'runsql'
           ) AS answer;

SELECT DBMS_CLOUD_AI.GENERATE(
             prompt       => 'Show the five service plans with the highest contracted monthly charges. Include plan name, category, summed line_total, and summed connection_count. Include only service_orders whose order_status is exactly ''confirmed'', ''active'', or ''completed'' (stored lowercase); exclude activation fees.',
             profile_name => 'genai',
             action       => 'narrate'
           ) AS explanation;

BEGIN
      DBMS_CLOUD_AI_AGENT.CREATE_TOOL(
        tool_name   => 'NINA_TELECOM_SQL_TOOL',
        attributes  => '{"tool_type": "SQL", "tool_params": {"profile_name": "genai"}}',
        description => 'Read-only SQL access to the workshop telecommunications tables'
      );
    END;
    /

BEGIN
      DBMS_CLOUD_AI_AGENT.CREATE_AGENT(
        agent_name  => 'NINA_TELECOM_AGENT',
        attributes  => '{"profile_name": "GENAI_AGENT", "role": "You are Nina Patel''s telecommunications data assistant. Answer questions using the approved SQL tool. Use database results for service plan, service order, monthly service charge, and subscriber facts. Do not invent values."}',
        description => 'Telecommunications assistant for Nina Patel'
      );
    END;
    /

BEGIN
      DBMS_CLOUD_AI_AGENT.CREATE_TASK(
        task_name  => 'NINA_TELECOM_TASK',
        attributes => '{"instruction": "Answer this telecommunications question: {query}. Send the complete question as natural language to NINA_TELECOM_SQL_TOOL with action runsql. The SQL tool generates SQL itself, so do not write SQL in its query argument. Call the tool only once. When the tool returns status success, immediately finish the task and give the user that result. Do not call the tool again after success. Do not change database records. Connections means SUM(service_order_lines.connection_count), not a count of orders.", "tools": ["NINA_TELECOM_SQL_TOOL"], "enable_human_tool": "false"}',
        description => 'Answer read-only service plan and subscriber questions'
      );
    END;
    /

BEGIN
      DBMS_CLOUD_AI_AGENT.CREATE_TEAM(
        team_name  => 'NINA_TELECOM_TEAM',
        attributes => '{"agents": [{"name": "NINA_TELECOM_AGENT", "task": "NINA_TELECOM_TASK"}], "process": "sequential"}',
        description => 'Read-only telecommunications question team'
      );
    END;
    /

SELECT DBMS_CLOUD_AI_AGENT.RUN_TEAM(
             team_name   => 'NINA_TELECOM_TEAM',
             user_prompt => 'Which five service plans have the highest contracted monthly charges? Sum service_order_lines.line_total only for service_orders whose order_status is exactly ''confirmed'', ''active'', or ''completed'' (stored lowercase). Include the service plan name, category, total monthly charges, and SUM(service_order_lines.connection_count) as connections ordered. Send this full question unchanged as natural language to the SQL tool, then finish with its successful result.',
             params      => '{"conversation_id": "' || DBMS_CLOUD_AI.CREATE_CONVERSATION() || '"}'
           ) AS agent_answer;

BEGIN
  DBMS_CLOUD_AI_AGENT.DROP_TEAM('NINA_TELECOM_TEAM', TRUE);
  DBMS_CLOUD_AI_AGENT.DROP_TASK('NINA_TELECOM_TASK', TRUE);
  DBMS_CLOUD_AI_AGENT.DROP_AGENT('NINA_TELECOM_AGENT', TRUE);
  DBMS_CLOUD_AI_AGENT.DROP_TOOL('NINA_TELECOM_SQL_TOOL', TRUE);
END;
